// "remove region count power entirely, have it be generated by the ai for
// every country by the scenario designer and that then ships with the scenario
// (like how politics generation works except everything is relative to every
// other country it generates and it doesnt waste an entire tool call per
// country or whatever, it does 20 countries per api call)" (the owner,
// 2026-10-16).
//
// In the Fronts section: the AI rates every country and group of the scenario
// against the others, twenty to a request (scenarioMilitary.js: who is asked
// next and what an answer writes; Game/AI/militaryRating.js: the request), and
// each batch is saved into the scenario as it comes, so a run stopped or failed
// half way keeps what it rated. "Rate every country" fills in what is missing
// (figures the designer set stand); "again" rates every one afresh.

import React, { useMemo, useRef, useState } from "react";

import { saveScenario } from "../../runtime/library.js";
import { eraOf } from "../../runtime/unitMotion.js";
import { normalizeWarSettings } from "../../runtime/warSettings.js";
import { rateMilitaryBatch } from "../AI/militaryRating.js";
import { nextMilitaryRequest, ratedKeys, scenarioMilitaryRoster, wantsMilitaryRating, withMilitaryRatings } from "./scenarioMilitary.js";

const buttonStyle = {
  alignItems: "center",
  background: "rgba(255,255,255,0.06)",
  border: "1px solid rgba(255,255,255,0.1)",
  borderRadius: "999px",
  color: "rgba(246,246,248,0.92)",
  cursor: "pointer",
  display: "inline-flex",
  fontSize: "0.76rem",
  fontWeight: 700,
  gap: "0.35rem",
  justifyContent: "center",
  minHeight: "2rem",
  padding: "0 0.8rem",
};
const primaryButtonStyle = { ...buttonStyle, background: "rgba(43,193,243,0.16)", borderColor: "rgba(43,193,243,0.4)", color: "#e0f6fe" };
const hintStyle = { color: "rgba(255,255,255,0.5)", fontSize: "0.7rem", lineHeight: 1.5 };

//   details           the scenario as the editor holds it; onDetailsChange(saved) after each batch is saved
//   gameDate          the scenario's date; warSettings, how its wars are fought (its era)
const ScenarioMilitaryPanel = ({ details, onDetailsChange, gameDate = "", warSettings = null }) => {
  const scenarioId = details?.scenario?.id ?? "";
  const roster = useMemo(() => scenarioMilitaryRoster(details?.data?.world ?? {}), [details]);
  const rated = roster.filter((entry) => !wantsMilitaryRating(entry)).length;
  const [running, setRunning] = useState(false);
  const [progress, setProgress] = useState("");
  const [message, setMessage] = useState("");
  const [error, setError] = useState("");
  const stopped = useRef(false);

  const run = async (again) => {
    if (running || !scenarioId || roster.length === 0) return;
    if (again && typeof window !== "undefined" && !window.confirm("Rate every country again? The figures already set, by you or by the AI, are replaced.")) return;
    stopped.current = false;
    setRunning(true);
    setError("");
    setMessage("");
    const tried = new Set();
    let current = details;
    let done = 0;
    try {
      for (;;) {
        if (stopped.current) {
          setMessage("Stopped. What was rated is saved with the scenario.");
          break;
        }
        const world = current?.data?.world ?? {};
        const list = scenarioMilitaryRoster(world);
        const request = nextMilitaryRequest(list, { tried, again });
        if (!request) {
          setMessage("Every country has its figures.");
          break;
        }
        const from = done + 1;
        const to = done + (request.polities?.length ?? 0);
        const count = list.length;
        setProgress(request.pickFrom ? "Rating the strongest twenty first…" : `Rating ${from} to ${to} of ${count}…`);
        const settings = normalizeWarSettings(warSettings);
        const ratings = await rateMilitaryBatch({
          ...(request.pickFrom ? { pickFrom: request.pickFrom } : { polities: request.polities }),
          rated: request.rated,
          date: gameDate,
          era: eraOf(gameDate, settings?.era ?? null),
          rules: world.simulationRules ?? "",
        });
        // (Each is asked of once in a run: one the AI left out is not asked of again and again.)
        for (const key of request.pickFrom ? ratedKeys(list, ratings) : request.wanted.map((entry) => entry.key)) tried.add(key);
        const { world: next, written } = withMilitaryRatings(world, list, ratings, { again });
        done += written.length;
        if (written.length > 0) {
          const saved = await saveScenario(scenarioId, { world: next });
          onDetailsChange?.(saved);
          current = saved;
        }
      }
    } catch (failure) {
      const why = String(failure?.message ?? failure);
      setError(`The AI could not rate them: ${why}`);
    } finally {
      setRunning(false);
      setProgress("");
    }
  };

  return (
    <div data-oh-scenario-military="" style={{ background: "rgba(255,255,255,0.03)", border: "1px solid rgba(255,255,255,0.08)", borderRadius: "18px", marginBottom: "0.95rem", padding: "0.9rem" }}>
      <div style={{ color: "rgba(255,255,255,0.94)", fontSize: "0.95rem", fontWeight: 800 }}>Countries' military figures</div>
      <div style={{ ...hintStyle, marginTop: "0.2rem" }}>
        The AI rates every country and group of this scenario against the others, twenty to a request: how well its soldiers fight, what they fight with, its army, navy and air force, what its forces have to spend, and its people where you gave none. What it says is saved with the scenario, and every game of it begins from it.
      </div>
      <div style={{ ...hintStyle, marginTop: "0.2rem" }}>
        A country you leave out is rated in the game, against the others, when it is first needed. You can change any country's figures in the map editor.
      </div>
      <div style={{ alignItems: "center", display: "flex", flexWrap: "wrap", gap: "0.5rem", marginTop: "0.8rem" }}>
        <span style={{ color: "rgba(255,255,255,0.78)", fontSize: "0.72rem", fontWeight: 700 }}>
          {`${rated} of ${roster.length} have their figures.`}
        </span>
        {running ? (
          <button className="oh-tap" onClick={() => { stopped.current = true; }} style={buttonStyle} type="button">Stop</button>
        ) : (
          <>
            <button className="oh-tap" disabled={!scenarioId || rated >= roster.length} onClick={() => run(false)} style={{ ...primaryButtonStyle, opacity: !scenarioId || rated >= roster.length ? 0.5 : 1 }} type="button">Rate every country</button>
            <button className="oh-tap" disabled={!scenarioId || roster.length === 0} onClick={() => run(true)} style={{ ...buttonStyle, opacity: !scenarioId || roster.length === 0 ? 0.5 : 1 }} type="button">Rate every country again</button>
          </>
        )}
      </div>
      {progress ? <div aria-live="polite" style={{ ...hintStyle, color: "rgba(255,255,255,0.72)", marginTop: "0.5rem" }}>{progress}</div> : null}
      {message ? <div aria-live="polite" style={{ ...hintStyle, marginTop: "0.5rem" }}>{message}</div> : null}
      {error ? <div role="alert" style={{ ...hintStyle, color: "#fca5a5", marginTop: "0.5rem" }}>{error}</div> : null}
    </div>
  );
};

export default ScenarioMilitaryPanel;
